419	function discoverProjects(dirs) {
420	  const projects = [];
421	  for (const dir of dirs) {
422	    const resolved = dir.replace(/^~/, HOME);
423	    if (!fs.existsSync(resolved)) continue;
424	    try {
425	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
426	      for (const entry of entries) {
427	        if (!entry.isDirectory()) continue;
428	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
429	        const projectPath = path.join(resolved, entry.name);
430	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
431	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
432	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
433	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
434	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
435	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
436	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
437	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
438	          projects.push({
439	            id: Buffer.from(projectPath).toString('base64url'),
440	            name: entry.name,
441	            path: projectPath,
442	            displayPath: projectPath.replace(HOME, '~'),
443	            hasClaudeDir,
444	            hasClaudeMd,
445	            agentCount: agents.length,
446	            commandCount: commands.length,
447	            ruleCount: rules.length,
448	            agents,
449	            commands: commands.map(c => c.name),
450	            rules: rules.map(r => r.name),
451	          });
452	        }
453	      }
454	    } catch {}
455	  }
456	  return projects;
457	}
